 mark=collections.Counter(x for row in grid for x in row if x!=bg).most_common(1)[0][0]
 ps=[(r,c) for r,row in enumerate(grid) for c,x in enumerate(row) if x==mark]
 H,W=len(grid),len(grid[0]); top=min(r for r,c in ps);bot=max(r for r,c in ps)
 out=[row[:] for row in grid]
 for r in {top,bot}:
  cs=[c for rr,c in ps if rr==r]
  for c in range(min(cs),max(cs)+1):
   if out[r][c]==bg:out[r][c]=2
 for c in range(W):
  rs=[r for r,cc in ps if cc==c]
  if len(rs)>=3:
   lo,hi=(top,bot) if vcol=='global' else (min(rs),max(rs))
   for r in range(lo,hi+1):
    if out[r][c]==bg:out[r][c]=2
 return out
